content.text:
{
  "status": "unavailable",
  "reason": "missing_brain",
  "why": "The brain configured in {{HOME}}/.gbrain/config.json is not at {{HOME}}/mnt/external/gbrain/brain.pglite (an unmounted drive or a moved folder?), so this server cannot open it. Nothing was created there.",
  "brain_path": "{{HOME}}/mnt/external/gbrain/brain.pglite",
  "config_path": "{{HOME}}/.gbrain/config.json",
  "fix": {
    "mcp": {
      "tool": "gbrain_status",
      "arguments": {}
    },
    "consent": [],
    "actor": "user",
    "why": "Mount or reconnect the drive that holds {{HOME}}/mnt/external/gbrain/brain.pglite, or point `database_path` in {{HOME}}/.gbrain/config.json at where the brain lives now; then call gbrain_status again and this server opens the brain in place. If your client does not refresh its tool list after recovery, restart this MCP server.",
    "user_message": "Your gbrain brain is configured at {{HOME}}/mnt/external/gbrain/brain.pglite, but nothing is there right now. Is it on a drive that needs mounting, or did it move? Once it's back I'll reconnect. If it's gone for good I can create a new empty brain, but your old notes would not be in it.",
    "verify": {
      "argv": [
        "gbrain",
        "doctor",
        "--only",
        "connection",
        "--json"
      ]
    },
    "requires_exclusive": false
  },
  "user_message": "Your gbrain brain is configured at {{HOME}}/mnt/external/gbrain/brain.pglite, but nothing is there right now. Is it on a drive that needs mounting, or did it move? Once it's back I'll reconnect. If it's gone for good I can create a new empty brain, but your old notes would not be in it.",
  "decisions": [
    {
      "id": "missing_brain_recovery",
      "question": "The brain at {{HOME}}/mnt/external/gbrain/brain.pglite is not there. Bring it back, or start a new empty brain?",
      "options": [
        {
          "id": "reconnect",
          "label": "Mount or move the brain back; this server reconnects on the next gbrain_status call."
        },
        {
          "id": "new_brain",
          "label": "Create a new, empty keyless brain at that path (the old notes are not in it).",
          "argv": [
            "gbrain",
            "init",
            "--pglite",
            "--no-embedding",
            "--path",
            "{{HOME}}/mnt/external/gbrain/brain.pglite"
          ]
        }
      ],
      "default": "reconnect",
      "default_reason": "Nothing is created or overwritten; the user's existing brain comes back as soon as its drive does."
    }
  ],
  "checked_at": "{{TIME}}",
  "contract_version": 1
}
